package com.alsafa.native4.core;
import android.content.ContentValues;import android.database.sqlite.SQLiteDatabase;import org.json.JSONObject;
/** Applies remote operations without generating another outbox event. Deletes are explicit tombstones only. */
public final class Native4OperationApplier implements Native4SyncReceiver.Applier{
 @Override public void apply(SQLiteDatabase db,Native4SyncReceiver.RemoteOp op)throws Exception{JSONObject j=new JSONObject(op.payload);switch(op.kind){case "PRODUCT_CREATE":case "PRODUCT_UPDATE":productUpsert(db,op.recordId,j);break;case "PRODUCT_DELETE":productDelete(db,op.recordId,j);break;case "INVENTORY_ADJUSTMENT":inventory(db,op.recordId,j);break;case "REPAIR":case "REPAIR_UPDATE":repair(db,op.recordId,j);break;case "SALE":case "SALE_CREATE":sale(db,op,j);break;case "CASH_MOVEMENT":cash(db,op,j);break;default:throw new IllegalArgumentException("نوع عملية الاستقبال غير مدعوم بعد: "+op.kind);}}
 private static void productUpsert(SQLiteDatabase db,String id,JSONObject j){ContentValues v=new ContentValues();v.put("product_id",id);put(v,"name",j,"name");put(v,"barcode",j,"barcode");put(v,"brand",j,"brand");if(j.has("reference"))v.put("ref",j.optString("reference"));put(v,"category",j,"category");if(j.has("dialColor"))v.put("dial_color",j.optString("dialColor"));if(j.has("caseColor"))v.put("case_color",j.optString("caseColor"));if(j.has("strapColor"))v.put("strap_color",j.optString("strapColor"));put(v,"currency",j,"currency");putDouble(v,"cost_price",j,"costPrice");putDouble(v,"sale_price",j,"salePrice");putInt(v,"quantity",j,"quantity");long now=j.optLong("updatedAt",System.currentTimeMillis());v.put("updated_at",now);v.put("created_at",j.optLong("createdAt",now));v.putNull("deleted_at");db.insertWithOnConflict("products",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
 private static void productDelete(SQLiteDatabase db,String id,JSONObject j){ContentValues v=new ContentValues();v.put("deleted_at",j.optLong("deletedAt",j.optLong("updatedAt",System.currentTimeMillis())));v.put("updated_at",j.optLong("updatedAt",System.currentTimeMillis()));db.update("products",v,"product_id=?",new String[]{id});}
 private static void inventory(SQLiteDatabase db,String id,JSONObject j){if(!j.has("quantity")&&!j.has("stockAfter"))throw new IllegalArgumentException("كمية المخزون مفقودة");ContentValues v=new ContentValues();v.put("quantity",j.has("stockAfter")?j.optInt("stockAfter"):j.optInt("quantity"));v.put("updated_at",j.optLong("updatedAt",System.currentTimeMillis()));db.update("products",v,"product_id=? AND deleted_at IS NULL",new String[]{id});}
 private static void repair(SQLiteDatabase db,String id,JSONObject j){long now=j.optLong("updatedAt",System.currentTimeMillis());if(j.has("invoiceNo")){ContentValues v=new ContentValues();v.put("repair_id",id);v.put("invoice_no",j.optString("invoiceNo"));v.put("customer_name",j.optString("customerName","عميل"));v.put("customer_phone",j.optString("customerPhone",""));v.put("watch_description",j.optString("watchDescription","صيانة"));v.put("status",j.optString("status","RECEIVED"));v.put("total",j.optDouble("total"));v.put("currency",j.optString("currency","USD"));v.put("payment_method",j.optString("paymentMethod","CASH"));v.put("received_at",now);v.put("updated_at",now);db.insertWithOnConflict("repairs",null,v,SQLiteDatabase.CONFLICT_IGNORE);}else if(j.has("status")){ContentValues v=new ContentValues();v.put("status",j.optString("status"));v.put("updated_at",now);if("DELIVERED".equals(j.optString("status")))v.put("delivered_at",now);db.update("repairs",v,"repair_id=? AND deleted_at IS NULL",new String[]{id});}if(j.has("partId")&&j.has("stockAfter")){ContentValues p=new ContentValues();p.put("quantity",j.optInt("stockAfter"));p.put("updated_at",now);db.update("repair_part_catalog",p,"part_id=? AND deleted_at IS NULL",new String[]{j.optString("partId")});}}
 private static void sale(SQLiteDatabase db,Native4SyncReceiver.RemoteOp op,JSONObject j){if(!j.has("invoiceNo"))throw new IllegalArgumentException("رقم فاتورة البيع مفقود");long now=j.optLong("updatedAt",System.currentTimeMillis());ContentValues v=new ContentValues();v.put("invoice_id",op.recordId);v.put("invoice_no",j.optString("invoiceNo"));v.put("invoice_type","SALE");v.put("currency",j.optString("currency","USD"));v.put("subtotal",j.optDouble("subtotal"));v.put("discount",j.optDouble("discount"));v.put("total",j.optDouble("total"));v.put("payment_method",j.optString("paymentMethod","CASH"));v.put("created_at",now);v.put("updated_at",now);db.insertWithOnConflict("invoices",null,v,SQLiteDatabase.CONFLICT_IGNORE);if(j.has("productId")){String itemId="remote-item-"+op.id;ContentValues it=new ContentValues();it.put("item_id",itemId);it.put("invoice_id",op.recordId);it.put("product_id",j.optString("productId"));it.put("description",j.optString("productName","منتج مبيع"));it.put("quantity",Math.max(1,j.optInt("quantity",1)));double subtotal=j.optDouble("subtotal");int q=Math.max(1,j.optInt("quantity",1));it.put("unit_price",subtotal/q);it.put("total",subtotal);it.put("unit_cost_snapshot",j.optDouble("unitCostSnapshot"));it.put("cost_total_snapshot",j.optDouble("capitalSnapshot"));it.put("profit_snapshot",j.optDouble("profitSnapshot"));it.put("created_at",now);db.insertWithOnConflict("invoice_items",null,it,SQLiteDatabase.CONFLICT_IGNORE);if(j.has("stockAfter")){ContentValues p=new ContentValues();p.put("quantity",j.optInt("stockAfter"));p.put("updated_at",now);db.update("products",p,"product_id=? AND deleted_at IS NULL",new String[]{j.optString("productId")});}}if(!"LATER".equals(j.optString("paymentMethod"))){ContentValues c=new ContentValues();c.put("move_id","remote-sale-cash-"+op.id);c.put("source_type","SALE");c.put("source_id",op.recordId);c.put("direction","IN");c.put("amount",j.optDouble("total"));c.put("currency",j.optString("currency","USD"));String pay=j.optString("paymentMethod","CASH");c.put("payment_method",pay);c.put("drawer",drawer(pay));c.put("created_at",now);db.insertWithOnConflict("cash_moves",null,c,SQLiteDatabase.CONFLICT_IGNORE);}}
 private static void cash(SQLiteDatabase db,Native4SyncReceiver.RemoteOp op,JSONObject j){if(!j.has("paidOutAmount"))throw new IllegalArgumentException("حركة الصندوق غير مدعومة بعد");ContentValues c=new ContentValues();c.put("move_id",j.optString("changeId","remote-cash-"+op.id));c.put("source_type","SALE_CHANGE_FX");c.put("source_id",j.optString("invoiceId",op.recordId));c.put("direction","OUT");c.put("amount",j.optDouble("paidOutAmount"));c.put("currency",j.optString("paidOutCurrency","USD"));c.put("payment_method","CASH");c.put("drawer",j.optString("drawer","MAIN"));c.put("created_at",j.optLong("updatedAt",System.currentTimeMillis()));db.insertWithOnConflict("cash_moves",null,c,SQLiteDatabase.CONFLICT_IGNORE);}
 private static String drawer(String p){if("SHAM_CASH".equals(p))return "SHAM_CASH";if("BANK".equals(p))return "BANK";if("EXTERNAL".equals(p))return "EXTERNAL";return "MAIN";}private static void put(ContentValues v,String col,JSONObject j,String key){if(j.has(key)&&!j.isNull(key))v.put(col,j.optString(key));}private static void putDouble(ContentValues v,String col,JSONObject j,String key){if(j.has(key)&&!j.isNull(key))v.put(col,j.optDouble(key));}private static void putInt(ContentValues v,String col,JSONObject j,String key){if(j.has(key)&&!j.isNull(key))v.put(col,j.optInt(key));}
}
